import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import * as esbuild from 'esbuild';

const __filename = fileURLToPath(import.meta.url);
const desktopDir = path.dirname(__filename);
const projectRoot = path.resolve(desktopDir, '..');
const bundleDir = path.join(desktopDir, 'bundle');
const distSrc = path.join(projectRoot, 'dist');
const distDest = path.join(bundleDir, 'dist');
const serverEntry = path.join(projectRoot, 'server.ts');
const serverOut = path.join(bundleDir, 'server.cjs');

console.log('[desktop:prepare] 0/3 Ensuring desktop icons & DMG background assets...');
execSync('node scripts/generate-desktop-icons.mjs', { cwd: projectRoot, stdio: 'inherit' });

console.log('[desktop:prepare] 1/3 Building frontend bundle (vite build)...');
execSync('npm run build', { cwd: projectRoot, stdio: 'inherit' });

if (!fs.existsSync(path.join(distSrc, 'index.html'))) {
  throw new Error('dist/index.html was not generated by vite build');
}

console.log('[desktop:prepare] 2/3 Copying frontend dist into desktop/bundle/dist...');
fs.rmSync(bundleDir, { recursive: true, force: true });
fs.mkdirSync(bundleDir, { recursive: true });
fs.cpSync(distSrc, distDest, { recursive: true });

console.log('[desktop:prepare] 3/3 Bundling standalone server.ts -> desktop/bundle/server.cjs...');
await esbuild.build({
  entryPoints: [serverEntry],
  bundle: true,
  platform: 'node',
  target: 'node20',
  format: 'cjs',
  outfile: serverOut,
  sourcemap: false,
  minify: false,
  external: [
    'vite',
    '@vitejs/plugin-react',
    '@tailwindcss/vite',
    'vite-plugin-pwa',
    'electron',
    'fsevents',
  ],
});

// Include minimal package.json metadata for runtime version reporting
const rootPkg = JSON.parse(
  fs.readFileSync(path.join(projectRoot, 'package.json'), 'utf-8')
);
fs.writeFileSync(
  path.join(bundleDir, 'package.json'),
  JSON.stringify(
    {
      name: rootPkg.name || 'etalon-pravilo-studio',
      version: rootPkg.version || '1.2.0',
    },
    null,
    2
  ),
  'utf-8'
);

console.log('[desktop:prepare] Done. Standalone desktop bundle ready at desktop/bundle/');
